@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLower()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }
}

@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title))
            return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
        ResetForm();
    }

    private async Task Cancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="board-stats">
    <span class="stat">Total: @Tasks.Count</span>
    <span class="stat">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="stat">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="stat">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="stat stat-overdue">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();
}

@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="board-column">
    <h3>@ColumnName (@Tasks.Count)</h3>

    @foreach (var task in Tasks)
    {
        <TaskCard Task="task"
                  CanMoveLeft="ColumnIndex > 0"
                  CanMoveRight="ColumnIndex < 2"
                  OnMoveLeft="() => MoveLeft(task)"
                  OnMoveRight="() => MoveRight(task)" />
    }

    @if (showAddForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="() => showAddForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter]
    public int ColumnIndex { get; set; }

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showAddForm;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private async Task MoveLeft(TaskItem task)
    {
        if (ColumnIndex > 0)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex - 1]));
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        if (ColumnIndex < 2)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex + 1]));
        }
    }

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showAddForm = false;
    }
}

@page "/board"
@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        @for (int i = 0; i < columns.Length; i++)
        {
            var index = i;
            <BoardColumn ColumnName="@columns[index]"
                         ColumnIndex="index"
                         Tasks="GetFilteredTasksForColumn(columns[index])"
                         OnMoveTask="HandleMoveTask"
                         OnAddTask="(model) => HandleAddTask(model, columns[index])" />
        }
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? errorMessage;

    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private List<TaskItem> GetFilteredTasksForColumn(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            tasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

