@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board

<div class="board-column">
    <h3>@ColumnName (@Tasks.Count)</h3>

    @foreach (var task in Tasks)
    {
        <TaskCard Task="task"
                  CanMoveLeft="ColumnIndex > 0"
                  CanMoveRight="ColumnIndex < 2"
                  OnMoveLeft="() => MoveLeft(task)"
                  OnMoveRight="() => MoveRight(task)" />
    }

    @if (showAddForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="() => showAddForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter]
    public int ColumnIndex { get; set; }

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showAddForm;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private async Task MoveLeft(TaskItem task)
    {
        if (ColumnIndex > 0)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex - 1]));
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        if (ColumnIndex < 2)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex + 1]));
        }
    }

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showAddForm = false;
    }
}

@page "/board"
@namespace sv_528419c8ae8246808574211a8f9b7781.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        @for (int i = 0; i < columns.Length; i++)
        {
            var index = i;
            <BoardColumn ColumnName="@columns[index]"
                         ColumnIndex="index"
                         Tasks="GetFilteredTasksForColumn(columns[index])"
                         OnMoveTask="HandleMoveTask"
                         OnAddTask="(model) => HandleAddTask(model, columns[index])" />
        }
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? errorMessage;

    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private List<TaskItem> GetFilteredTasksForColumn(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            tasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

