    @foreach (var task in Tasks)
    {
        <TaskCard Task="task"
                  CanMoveLeft="ColumnIndex > 0"
                  CanMoveRight="ColumnIndex < 2"
                  OnMoveLeft="() => MoveLeft(task)"
                  OnMoveRight="() => MoveRight(task)" />
    }

    @if (showAddForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="() => showAddForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter]
    public int ColumnIndex { get; set; }

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showAddForm;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private async Task MoveLeft(TaskItem task)
    {
        if (ColumnIndex > 0)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex - 1]));
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        if (ColumnIndex < 2)
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex + 1]));
        }
    }

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showAddForm = false;
    }
}

