    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

.board-stats {
    display: flex;
    gap: 1rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-stats .stat {
    padding: 0.5rem 1rem;
    background: white;
    border-radius: 4px;
    font-weight: 500;
    border: 1px solid #dee2e6;
}

.board-stats .stat-overdue {
    color: #dc3545;
    border-color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 1rem;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

.board-column h3 {
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
}

.task-card {
    background: white;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
    border: 1px solid #dee2e6;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

.task-card h4 {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #dc3545;
    color: white;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: white;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
    margin-left: 0.5rem;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.25rem;
}

.btn-move {
    padding: 0.2rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    background: white;
    border-radius: 3px;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    border-radius: 4px;
    cursor: pointer;
    color: #6c757d;
    margin-top: 0.5rem;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: white;
    border-radius: 6px;
    border: 1px solid #dee2e6;
    margin-top: 0.5rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.error {
    color: #dc3545;
    padding: 1rem;
    background: #f8d7da;
    border-radius: 4px;
}

